import RNA
import random

target = '.....((((.(...(.((((.(.((((.((.((((.((.(((....))).).)))))).).))))....).)))).)...).))))....................'
n = len(target)

# base pair list
stack=[]
pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j

paired = [i for i in range(n) if i in pairs]
unpaired = [i for i in range(n) if i not in pairs]

def bp_distance(struct, target):
    # count differing positions in pair table? use RNA lib
    return RNA.bp_distance(struct, target)

def random_seq_from(seed_seq=None):
    bases='ACGU'
    comp = {'A':'U','U':'A','G':'C','C':'G'}
    wobble_extra = {'G':'U','U':'G'}
    seq = [None]*n
    for i in range(n):
        if i in pairs and pairs[i] > i:
            j = pairs[i]
            b1 = random.choice(bases)
            # choose complementary strong pair (GC/AU/GU) most of time
            r = random.random()
            if r < 0.6:
                if b1 in ('G','C'):
                    b2 = comp[b1]
                else:
                    b2 = comp[b1]
            else:
                b2 = random.choice(bases)
            seq[i]=b1
            seq[j]=b2
    for i in unpaired:
        seq[i] = random.choice(bases)
    return ''.join(seq)

def mutate(seq):
    seq = list(seq)
    i = random.randrange(n)
    bases='ACGU'
    if i in pairs:
        j = pairs[i]
        comp = {'A':'U','U':'A','G':'C','C':'G'}
        b1 = random.choice(bases)
        if random.random()<0.7:
            b2 = comp[b1]
        else:
            b2 = random.choice(bases)
        seq[i]=b1
        seq[j]=b2
    else:
        seq[i] = random.choice(bases)
    return ''.join(seq)

def score(seq):
    fc = RNA.fold_compound(seq)
    mfe_struct, mfe_energy = fc.mfe()
    d = bp_distance(mfe_struct, target)
    return d, mfe_struct, mfe_energy

best_overall = None
best_overall_d = 999

random.seed(1)
for restart in range(60):
    seq = random_seq_from()
    d, struct, energy = score(seq)
    cur_seq, cur_d = seq, d
    T = 2.0
    for step in range(3000):
        cand = mutate(cur_seq)
        d, struct, energy = score(cand)
        if d <= cur_d or random.random() < 0.02:
            cur_seq, cur_d = cand, d
        if cur_d == 0:
            break
        T *= 0.999
    if cur_d < best_overall_d:
        best_overall_d = cur_d
        best_overall = cur_seq
        print('restart', restart, 'best_d', best_overall_d, best_overall)
    if best_overall_d == 0:
        break

print('FINAL', best_overall_d, best_overall)
